    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                idx[(i, j)] = len(empty)
                empty.append((i, j))
    n = len(empty)
    adj = [[] for _ in range(n)]
    for a, (i, j) in enumerate(empty):
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if (ni, nj) in idx:
                adj[a].append(idx[(ni, nj)])

    # state: (cell, visited mask) -> count
    cur = {}
    for a in range(n):
        key = (a, 1 << a)
        cur[key] = cur.get(key, 0) + 1
    for _ in range(K):
        nxt = {}
        for (a, mask), c in cur.items():
            for b in adj[a]:
                bit = 1 << b
                if mask & bit:
                    continue
                key = (b, mask | bit)
                nxt[key] = nxt.get(key, 0) + c
        cur = nxt
    total = 0
    for c in cur.values():
        total += c
    print(total)

